        <input id="address" @bind="Shipping.Address" @bind:event="oninput" disabled="@_isValidating" />
    </div>

    <div class="form-group">
        <label for="city">City</label>
        <input id="city" @bind="Shipping.City" @bind:event="oninput" disabled="@_isValidating" />
    </div>

    <div class="form-group">
        <label for="zip">Zip Code</label>
        <input id="zip" @bind="Shipping.ZipCode" @bind:event="oninput" disabled="@_isValidating" />
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-error" role="alert">@_validationError</div>
    }

    <div class="step-actions">
        <button @onclick="ValidateAndProceed" disabled="@_isValidating">
            @if (_isValidating)
            {
                <span class="spinner" aria-hidden="true"></span>
                <span>Validating…</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter]
    public ShippingInfo Shipping { get; set; } = default!;

    [Parameter]
    public EventCallback OnNext { get; set; }

    private bool _isValidating;
    private string? _validationError;

    // Linked to _disposalCts so cancellation propagates on Dispose.
    private CancellationTokenSource? _validationCts;
    private readonly CancellationTokenSource _disposalCts = new();

    private async Task ValidateAndProceed()
    {
        _validationError = null;

        // Cancel any in-flight validation (e.g. user went back and changed fields).
        _validationCts?.Cancel();
        _validationCts?.Dispose();
        _validationCts = CancellationTokenSource.CreateLinkedTokenSource(_disposalCts.Token);

        var ct = _validationCts.Token;

        _isValidating = true;

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                Shipping.Address, Shipping.City, Shipping.ZipCode, ct);

            ct.ThrowIfCancellationRequested();

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _validationError = "The address could not be verified. Please check and try again.";
            }
        }
        catch (OperationCanceledException)
        {
            // Validation was cancelled — either by a new attempt or component disposal.
        }
        finally
        {
            // Only clear the spinner if this is still the active validation.
            if (_validationCts is not null && !_validationCts.IsCancellationRequested)
            {
                _isValidating = false;
            }
            else if (_disposalCts.IsCancellationRequested)
            {
                // Component is being disposed — don't touch UI state.
            }
            else
            {
                // A newer validation superseded this one; the newer call owns _isValidating.
            }
        }
    }

    public void Dispose()
    {
        _disposalCts.Cancel();
        _disposalCts.Dispose();
        _validationCts?.Cancel();
        _validationCts?.Dispose();
    }
}

